shader:
// The belt's chevrons run along it, half a texture each second.
fn surface(input: SurfaceInput) -> Surface {
    var moved = input;
    moved.uv = input.uv - vec2<f32>(input.time * 0.5, 0.0);
    var out = standard_surface(moved);
    // The yellow stripes glow a little, so they read in the shade.
    out.emissive = out.base_color * 0.15;
    return out;
}
